   if(kind==='idf-ota'&&s.slots[s.active].state==='PENDING_VERIFY')return fail('PENDING_VERIFY','当前新固件尚待确认，不能开始下一次 OTA。先自检确认或回滚。','The current app is pending verification. Confirm it after diagnostics or roll back before another OTA.');
